package norviq.remediation.capability.postgresql_delete_write_report_gen

# CAPABILITY POLICY — GENERATED, DRY-RUN DRAFT. Makes PostgreSQL delete/write-safe for agent
# class "report-gen": blocks any tool that performs those verbs (by verb-name pattern — a FORWARD GUARD
# for tools not yet seen — plus the concrete tools observed reaching it). The OPA input has no data-source
# field, so the source is resolved to verbs/tools at generation time. TIGHTEN-ONLY at baseline priority —
# only ADDS denials. NEVER auto-enforces — the operator reviews + applies via the gated Policies flow.

default decision = "allow"
default rule_id  = "capability_noop"
default reason   = "Allowed"

is_capability_class { input.agent.agent_class == "report-gen" }

cap_tools := {}

blocks["capability:postgresql:delete+write"] { is_capability_class; cap_tools[input.tool_name] }
# Evasion parity: also match the confusable-skeleton of the tool name (homoglyph/zero-width).
blocks["capability:postgresql:delete+write"] { is_capability_class; cap_tools[input.tool_name_normalized] }
cap_verb_pattern := "(^|[^a-z0-9])(truncate|delete|insert|modify|update|upsert|purge|write|drop|put)([^a-z0-9]|$)"
# Forward guard: block any tool whose name (or its confusable-normalized form) matches a target verb.
blocks["capability:postgresql:delete+write"] { is_capability_class; regex.match(cap_verb_pattern, lower(input.tool_name)) }
blocks["capability:postgresql:delete+write"] { is_capability_class; regex.match(cap_verb_pattern, lower(input.tool_name_normalized)) }

block_fired { blocks[_] }
decision = "block" { block_fired }
rule_id = sort([id | blocks[id]])[0] { block_fired }
reason = "Blocked: delete/write on PostgreSQL for this class (capability policy \u2014 least privilege)" { block_fired }

intent_compiled_in_empty.rego:
# GENERATED FROM AN INTENT — DO NOT EDIT BY HAND.
#
# Regenerate with norviq.engine.intent.compile_intent(). Hand edits are lost on the next compile and,
# worse, make the stored Rego disagree with the intent the console shows the operator.
#
#   intent : legacy-in
#   class  : report-gen
#   planes : call
#
# Positive security: every rule below is an ALLOW. There is no deny list — deny is the absence of a
# match, which is why `default decision` is "block".
#
# nrvq:intent-tools ["search_kb"]
#   The tool names this intent can ever admit, as a JSON array, for the console's coverage summary
#   (api/routers/coverage.py `_parse_agent_policy`). A MARKER, never enforcement: the real scoping is
#   the predicates below, and an intent that constrains no tool name emits [] — which honestly means
#   "this intent does not scope by tool name", not "it admits nothing".
package norviq.intent.report_gen


# Deny is the absence of a matching allow rule.
default decision = "block"
default rule_id = "intent_no_match"
default reason = "no intent rule matched this call"

# Membership helper. Inlined because this OPA cannot import across packages.
_in(haystack, needle) {
	haystack[_] == needle
}

# ---- plane: call ------------------------------------------------------------
_predicates["r-none"] = p {
	p := {
		"direction == call": object.get(input, "direction", "call") == "call",
		"tool_name in []": count([x | x := [][_]; x == input.tool_name]) > 0,
	}
}

_predicates["r-search"] = p {
	p := {
		"direction == call": object.get(input, "direction", "call") == "call",
		"tool_name == search_kb": input.tool_name == "search_kb",
	}
}

# Predicates that evaluated false, per rule — the near-miss data.
_failed[id] = fs {
	p := _predicates[id]
	fs := sort([k | p[k] == false])
}

_matched[id] {
	count(_failed[id]) == 0
}

_any_match {
	count(_matched) > 0
}

decision = "allow" {
	_any_match
}

# Deny, stated explicitly — see the note in compiler.py on why this is not redundant.
decision = "block" {
	not _any_match
}

# Sorted so a call matching two rules is attributed deterministically.
rule_id = id {
	_any_match
	id := sort([i | _matched[i]])[0]
}

reason = msg {
	_any_match
	id := sort([i | _matched[i]])[0]
	msg := sprintf("allowed by intent rule %v", [id])
}

# The near miss. Without it a denial says only "no rule matched", which is the
# absence of a rule — nothing an operator can act on. Naming the closest rule and the
# clause that failed is the difference between tightening a predicate and switching
# the policy off.
_min_failed = n {
	not _any_match
	counts := [c | _predicates[id]; c := count(_failed[id])]
	count(counts) > 0
	n := min(counts)
}

_closest[id] {
	count(_failed[id]) == _min_failed
}

reason = msg {
	not _any_match
	ids := sort([i | _closest[i]])
	count(ids) > 0
	id := ids[0]
	total := count(_predicates[id])
	met := total - count(_failed[id])
	msg := sprintf("no intent rule matched; closest %v met %v/%v, failed: %v",
		[id, met, total, concat(", ", _failed[id])])
}

mcp_registry_no_writable.rego:
# Generated by norviq/api/mcp_controls.py — DO NOT HAND-EDIT.
# Hand edits are overwritten the next time a server decision is saved, and desynchronise the header
# below, which is what the console reads the registry back from.
# nrvq-mcp-registry/v1: eyJyZWdpc3RlcmVkIjogWyJrYiJdLCAid3JpdGFibGUiOiBbXSwgInVucmVnaXN0ZXJlZF9kZWNpc2lvbiI6ICJhdWRpdCIsICJ3cml0ZV9kZWNpc2lvbiI6ICJibG9jayJ9
package norviq.mcp_registry

# The two MCP controls that need the customer's own list. The other five read only `input.mcp.*` and
# live in the preset's CONTROLS region.
#
# `input.mcp` is PEP-REPORTED. It is a POLICY input and never a TRUST input: nothing here decides WHO
# is calling. Identity comes from the attested SVID and is never read from an MCP message.

default decision = "allow"
default rule_id = "default_allow"
default reason = "Allowed"

registered_servers = {"kb"}
writable_servers = {}

# Only ever true for a call that CAME THROUGH the MCP proxy. Every other call in the estate — SDK,
# sidecar, webhook — has no `input.mcp` and is untouched by this module.
_is_mcp { input.mcp.server != "" }

# INERT ON AN EMPTY REGISTRY. Not "everything is unregistered": a fresh install would then flag every
# MCP call, and the first thing an operator would do is switch the control off. The registry fills as
# servers are discovered; registering one is what gives this control something to say.
_registry_populated { count(registered_servers) > 0 }

_unregistered {
    _is_mcp
    _registry_populated
    not registered_servers[input.mcp.server]
}

# A write through a server the operator did not mark writable. `derived.verb` is the engine's own
# classifier, so this agrees with every other verb-keyed rule in the product rather than re-deriving
# "is this a write" from the tool name. `unknown` is excluded: the classifier saying "I cannot tell"
# is not evidence of a write, and treating it as one would refuse ordinary reads it failed to label.
_unapproved_write {
    _is_mcp
    _registry_populated
    registered_servers[input.mcp.server]
    not writable_servers[input.mcp.server]
    input.derived.verb != "read"
    input.derived.verb != "unknown"
}

audits["mcp_unregistered_server"] { _unregistered }
blocks["mcp_unapproved_write_server"] { _unapproved_write }

decision = "audit" { _unregistered }
rule_id = "mcp_unregistered_server" { _unregistered }
reason = msg {
    _unregistered
    msg := sprintf("MCP server %v is not registered for this namespace", [input.mcp.server])
}

decision = "block" { _unapproved_write; not _unregistered }
rule_id = "mcp_unapproved_write_server" { _unapproved_write; not _unregistered }
reason = msg {
    _unapproved_write
    not _unregistered
    msg := sprintf("writes are not permitted through MCP server %v", [input.mcp.server])
}

